57	interface AnalyzerOptions {
58	  /**
59	   * Host module resolution. Maps an import specifier and the importing
60	   * module's path to the path of an added file, or null for external
61	   * modules. Defaults to relative-path resolution among added files
62	   * with standard extension and index probing.
63	   */
64	  resolve?: (specifier: string, importerPath: string) => string | null;
65	}
66	
67	/**
68	 * Bit flags describing a {@link Symbol}: which declaration kinds it
69	 * carries (one symbol can merge several under TS declaration merging)
70	 * and its modifiers, plus a few composite categories. Every categorical
71	 * question about a symbol is `symbol.has(SymbolFlags.X)` (any of the
72	 * bits) or `symbol.hasAll(...)` (all of them); there is one way to ask.
73	 */
74	declare const SymbolFlags: {
75	  /** `var`, parameter, or catch variable. */
76	  readonly FunctionScopedVariable: number;
77	  /** `let`, `const`, `using`, `await using`. */
78	  readonly BlockScopedVariable: number;
79	  /** Function declaration or expression. */
80	  readonly Function: number;
81	  /** Class declaration or expression. */
82	  readonly Class: number;
83	  /** TS `enum`. */
84	  readonly RegularEnum: number;
85	  /** TS `const enum`. */
86	  readonly ConstEnum: number;
87	  /** TS namespace with runtime content. */
88	  readonly ValueModule: number;
89	  /** TS `interface`. */
90	  readonly Interface: number;
91	  /** TS `type` alias. */
92	  readonly TypeAlias: number;
93	  /** TS `<T>`, `infer T`, or mapped-type key. */
94	  readonly TypeParameter: number;
95	  /** TS namespace of any kind. */
96	  readonly NamespaceModule: number;
97	  /** A value import binding (`import x` / `import { x }`). */
98	  readonly ValueImport: number;
99	  /** `import type` / `import { type x }` binding. */
100	  readonly TypeImport: number;
101	  /** `const` or `using` binding. */
102	  readonly Const: number;
103	  /** TS `declare`. */
104	  readonly Ambient: number;
105	  /** Function or method parameter. */
106	  readonly Parameter: number;
107	  /** `catch (e)` binding. */
108	  readonly CatchVariable: number;
109	  /** Exported from its module. */
110	  readonly Exported: number;
111	  /** The default export. */
112	  readonly Default: number;
113	  /** A TS enum member, declared in its enum's body scope. */
114	  readonly EnumMember: number;
115	
116	  /** Composite: any variable (`var` / `let` / `const`, params, catch). */
117	  readonly Variable: number;
118	  /** Composite: any import binding, value or `import type`. */
119	  readonly Import: number;
120	  /** Composite: visible at runtime (var, function, class, enum and its members, value namespace). */
121	  readonly ValueSpace: number;
122	  /** Composite: referencable from a type position (class, enum and its members, interface, alias, type param). */
123	  readonly TypeSpace: number;
124	  /** Composite: what a dotted type name starts from (namespace, enum). */
125	  readonly NamespaceSpace: number;
126	};
127	
128	/**
129	 * The declaration space a reference position resolves in, matching
130	 * TypeScript name resolution. A binding outside a reference's space
131	 * does not shadow: an inner `const T` never captures a type-position
132	 * `T` away from an outer `type T`, and vice versa.
133	 *
134	 * - `"value"`: runtime uses
135	 * - `"type"`: annotations, heritage clauses, type arguments
136	 * - `"namespace"`: the qualifier of a dotted type name (`ns.T`, `E.A`)
137	 * - `"typeof"`: value uses inside a type (`typeof x`, `x is T` params)
138	 * - `"any"`: alias positions accepting every space (`export { x }`,
139	 *   `export default x`, `export = x`, `import a = x`)
140	 */
141	type Space = "value" | "type" | "namespace" | "typeof" | "any";
142	
143	/** What kind of construct created a {@link Scope}. */
144	type ScopeKind =
145	  | "global"
146	  | "module"
147	  | "function"
148	  | "block"
149	  | "class"
150	  | "staticBlock"
151	  | "expressionName"
152	  | "tsModule"
153	  | "functionBody";
154	
155	/** A lexical scope in a module's scope tree. */
156	interface Scope {
157	  /** The owning module. */
158	  readonly module: Module;
159	  /** Stable id, the index into {@link Module.scopes}. */
160	  readonly id: number;
161	  readonly kind: ScopeKind;
162	  /** Whether this scope is in strict mode. */
163	  readonly strict: boolean;
164	  /** The AST node that created this scope. */
165	  readonly node: Node;
166	  /** The parent scope, or null for the global scope. */
167	  readonly parent: Scope | null;
168	  /** The nearest scope (or self) where `var` declarations land. */
169	  readonly hoistTarget: Scope;
170	  /** Symbols declared directly in this scope. */
171	  readonly bindings: Symbol[];
172	  /** Looks up `name` declared directly in this scope. */
173	  find(name: string): Symbol | null;
174	  /** True when `other` is this scope or a descendant of it. */
175	  contains(other: Scope): boolean;
176	  /** Walks from this scope up to the global scope, inclusive. */
177	  ancestors(): IterableIterator<Scope>;
178	}
179	
180	/**
181	 * A declared binding. One symbol can have several declarations under
182	 * TS declaration merging (overloads, class + interface, namespace
183	 * merges).
184	 */
185	interface Symbol {
186	  /** The owning module. */
187	  readonly module: Module;
188	  /**
189	   * Stable id, the index into {@link Module.symbols}. Deterministic per
190	   * parse: `(module.path, id)` is a persistable key.
191	   */
192	  readonly id: number;
193	  readonly name: string;
194	  /** Raw {@link SymbolFlags} bitset. */
195	  readonly flags: number;
196	  /** The scope this symbol is declared in. */
197	  readonly scope: Scope;
198	  /** Every declarator node, in source order. */
199	  readonly declarations: Node[];
200	  /** Every resolved use site within this module, in source order. */
201	  readonly references: Reference[];
202	  /**
203	   * True when any flag in `mask` is set. The single way to ask what a
204	   * symbol is: `symbol.has(SymbolFlags.Function)`, or a composite like
205	   * `symbol.has(SymbolFlags.ValueSpace)`.
206	   */
207	  has(mask: number): boolean;
208	  /** True when every flag in `mask` is set. */
209	  hasAll(mask: number): boolean;
210	  /**
211	   * True when a reference resolving in `space` may bind to this
212	   * symbol, the acceptance rule of name resolution. Import bindings
213	   * alias symbols of unknowable space and are visible in every space.
214	   */
215	  visibleIn(space: Space): boolean;
216	  /**
217	   * The defining site of this symbol, following import/re-export chains
218	   * across modules. Shorthand for {@link Analyzer.definitionOf}.
219	   */
220	  definition(): Definition | null;
221	}
222	
223	/** One use of a name: a single identifier in reference position. */
224	interface Reference {
225	  /** The owning module. */
226	  readonly module: Module;
227	  /** Stable id, the index into {@link Module.references}. */
228	  readonly id: number;
229	  readonly name: string;
230	  /** The scope the reference occurs in. */
231	  readonly scope: Scope;
232	  /** The identifier node, the same object as in the walked AST. */
233	  readonly node: Identifier | JSXIdentifier;
234	  /** The declaration {@link Space} this position resolves in. */
235	  readonly space: Space;
236	  /**
237	   * True when the position sits inside a type-only subtree (`"type"`,
238	   * `"namespace"`, `"typeof"` spaces): erased at compile time, so a
239	   * rename tool can change a value without touching a same-named type.
240	   */
241	  readonly inTypePosition: boolean;
242	  /**
243	   * True when this reference (re)assigns its binding: assignment
244	   * targets, `++`/`--` operands, for-in/of iteration variables, and
245	   * destructuring assignment leaves. Compound targets (`+=`) both read
246	   * and write.
247	   */
248	  readonly isWrite: boolean;
249	  /**
250	   * The symbol this resolves to, or null when no binding is visible
251	   * in this reference's space (globals, undeclared names).
252	   */
253	  readonly symbol: Symbol | null;
254	}
255	
256	/**
257	 * The semantic walk context: the toolchain's {@link BaseWalkContext} (the
258	 * same position info and mutation operations, exact same semantics)
259	 * plus the module's semantic surface. One object is reused across the
260	 * whole walk; do not hold onto it across nodes.
261	 *
262	 * On mutation: semantic tables are a snapshot of the parsed source, so
263	 * new nodes have no symbols, references, or spans of their own.
264	 * Analyze, transform, then print (or re-analyze the printed output for
265	 * fresh semantics).
266	 */
267	declare class WalkContext<T extends Node = Node> extends BaseWalkContext<T> {
268	  /** The module being walked. Every semantic query is in reach. */
269	  readonly module: Module;
270	  /**
271	   * The innermost scope at the current node, replayed from the native
272	   * scope tree (catch-scope sharing, named-expression scopes, and
273	   * hoist targets are all exact).
274	   */
275	  readonly scope: Scope;
276	  /** Shorthand for `module.symbolOf(node)`. */
277	  readonly symbol: Symbol | null;
278	  /** Shorthand for `module.referenceOf(node)`. */
279	  readonly reference: Reference | null;
280	}
281	
282	/** Handler invoked with the precisely-typed node and the walk context. */
283	type WalkHandler<T extends Node = Node> = (node: T, ctx: WalkContext<T>) => void;
284	
285	/** Enter/leave pair for one node type. */
286	interface WalkHooks<T extends Node = Node> {
287	  enter?: WalkHandler<T>;
288	  leave?: WalkHandler<T>;
289	}
290	
291	/**
292	 * Visitors passed to {@link Module.walk}: keys are node `type` strings, plus optional `enter` /
293	 * `leave` catch-alls. Order per node: catch-all `enter`, typed enter,
294	 * children, typed leave, catch-all `leave`.
295	 */
296	type Visitors = {
297	  [K in NodeType]?: WalkHandler<NodeOfType<K>> | WalkHooks<NodeOfType<K>>;
298	} & {
299	  enter?: WalkHandler;
300	  leave?: WalkHandler;
301	};
302	
303	/** Handler for one node type in an async walk, free to return a promise. */
304	type AsyncWalkHandler<T extends Node = Node> = (node: T, ctx: WalkContext<T>) => void | Promise<void>;
305	
306	/** Enter/leave pair for one node type in an async walk. */
307	interface AsyncWalkHooks<T extends Node = Node> {
308	  enter?: AsyncWalkHandler<T>;
309	  leave?: AsyncWalkHandler<T>;
310	}
311	
312	/** {@link Visitors}, with handlers that may return promises. */
313	type AsyncVisitors = {
314	  [K in NodeType]?: AsyncWalkHandler<NodeOfType<K>> | AsyncWalkHooks<NodeOfType<K>>;
315	} & {
316	  enter?: AsyncWalkHandler;
317	  leave?: AsyncWalkHandler;
318	};
319	
320	/** A free variable of a function, as reported by {@link Module.capturesOf}. */
321	interface Capture {
322	  /** The outer binding being closed over. */
323	  readonly symbol: Symbol;
324	  /** The capturing reference sites inside the function. */
325	  readonly references: Reference[];
326	  /** True when the function writes to the binding. */
327	  readonly isWritten: boolean;
328	}
329	
330	/** One imported binding (or side-effect import) of a module. */
331	interface Import {
332	  /** The importing module. */
333	  readonly module: Module;
334	  /** Stable id, the index into {@link Module.imports}. */
335	  readonly id: number;
336	  /** The local binding symbol, or null for side-effect imports. */
337	  readonly local: Symbol | null;
338	  /**
339	   * The imported export name, `"default"` for default imports (the
340	   * spec models default as a name). Null for namespace and side-effect
341	   * imports.
342	   */
343	  readonly name: string | null;
344	  /** True for `import * as ns`. */
345	  readonly isNamespace: boolean;
346	  /** True for bare `import "m"`. */
347	  readonly isSideEffect: boolean;
348	  /** True for `import type` / `import { type x }`. */
349	  readonly typeOnly: boolean;
350	  /** Stage 3 phase modifier, or null. */
351	  readonly phase: "source" | "defer" | null;
352	  readonly specifier: string;
353	  /** The specifier node (the declaration for side-effect imports). */
354	  readonly node: Node;
355	  /** The defining module, or null when external. Links on demand. */
356	  readonly resolvedModule: Module | null;
357	}
358	
359	/** One exported name of a module. */
360	interface Export {
361	  /** The exporting module. */
362	  readonly module: Module;
363	  /** Stable id, the index into {@link Module.exports}. */
364	  readonly id: number;
365	  /**
366	   * The exported name (`"default"` included), or null for `export *`,
367	   * `export =`, and `export as namespace`.
368	   */
369	  readonly name: string | null;
370	  /** True for `export * from "m"` without an alias. */
371	  readonly isStar: boolean;
372	  /** True for TS `export = expr` (the module's entire export value). */
373	  readonly isExportEquals: boolean;
374	  /** The TS `export as namespace N` global name, or null. */
375	  readonly globalName: string | null;
376	  readonly typeOnly: boolean;
377	  /** The backing local symbol, or null (re-exports, anonymous defaults). */
378	  readonly local: Symbol | null;
379	  /** The re-export source specifier, or null for local exports. */
380	  readonly specifier: string | null;
381	  /** The name taken from the source module, or null (namespace / `export *`). */
382	  readonly fromName: string | null;
383	  /** True for `export *` and `export * as ns from "m"`. */
384	  readonly isNamespaceReexport: boolean;
385	  readonly node: Node;
386	  /** The re-export source module, or null. Links on demand. */
387	  readonly resolvedModule: Module | null;
388	}
389	
390	/**
391	 * One analyzed source file: its AST, per-file semantics, and module
392	 * records. Created by {@link Analyzer.addFile}. All queries are local
393	 * (no native calls).
394	 */
395	interface Module {
396	  readonly analyzer: Analyzer;
397	  readonly path: string;
398	  readonly source: string;
399	
400	  /**
401	   * The ESTree / TypeScript-ESTree program. Lazily decoded. Nodes are
402	   * identity-shared with every semantic query result.
403	   *
404	   * Nodes are plain mutable objects: edit them in place, mutate them
405	   * during a walk with {@link WalkContext.replace} and friends, and
406	   * print the result with `yuku-codegen`. Semantic tables stay a
407	   * snapshot of the parsed source and do not track mutations.
408	   */
409	  readonly ast: Program;
410	  /** Syntax and semantic diagnostics for this file. */
411	  readonly diagnostics: Diagnostic[];
412	  /** Every comment in source order. */
413	  readonly comments: Comment[];
414	
415	  /** Every lexical scope; index is the scope id. `scopes[0]` is global. */
416	  readonly scopes: Scope[];
417	  /** The scope top-level code runs in: module scope, or global for scripts. */
418	  readonly rootScope: Scope;
419	  /** Every declared symbol; index is the symbol id. */
420	  readonly symbols: Symbol[];
421	  /** Every identifier reference in source order; index is the reference id. */
422	  readonly references: Reference[];
423	  /** References resolving to no binding: globals and free names. */
424	  readonly unresolvedReferences: Reference[];
425	
426	  /**
427	   * The symbol a node refers to: its own symbol for a declaration
428	   * identifier, the resolved symbol for a reference identifier. Null
429	   * for nodes that are neither, or for unresolved references.
430	   */
431	  symbolOf(node: Node): Symbol | null;
432	  /** The reference recorded for an identifier node, or null. */
433	  referenceOf(node: Node): Reference | null;
434	  /**
435	   * The innermost scope whose extent contains `node`, or the module's
436	   * root scope for a node not produced by this module's analysis.
437	   */
438	  scopeOf(node: Node): Scope;
439	  /**
440	   * The node that structurally contains `node`. Null at the program
441	   * root and for a node not part of this module's AST. Lets you walk
442	   * upward from a node you already hold, with no ancestor stack.
443	   */
444	  parentOf(node: Node): Node | null;
445	  /**
446	   * Walks the scope chain from `from` (default: the root scope) to
447	   * find the nearest binding of `name` visible in `space` (default:
448	   * `"value"`, resolving like runtime code). A binding outside the
449	   * space does not shadow, the walk keeps going. `"any"` matches by
450	   * name alone. A value-position `arguments` lookup stops at the
451	   * first non-arrow function or static block, where the implicit
452	   * arguments object shadows any outer binding of that name.
453	   */
454	  resolve(name: string, from?: Scope, space?: Space): Symbol | null;
455	  /**
456	   * The free variables of a function or arrow: every binding referenced
457	   * inside it (nested closures included, value positions only) that is
458	   * declared outside it. Shadowing- and alias-correct, because it rides
459	   * the resolved reference table.
460	   *
461	   * Only bindings count: `this`, `arguments`, and unresolved/global
462	   * names carry no symbol and never appear. Module-scope and import
463	   * bindings count like any other outer binding; filter on the
464	   * symbol's scope to narrow.
465	   *
466	   * Throws when `node` is not a function of this module's AST.
467	   */
468	  capturesOf(node: Node): Capture[];
469	  /**
470	   * Every name this module exports, directly or through `export *`
471	   * chains (the spec's GetExportedNames). Ambiguous star names are
472	   * included; `"default"` never crosses an `export *` boundary. Links
473	   * on demand.
474	   */
475	  exportedNames(): string[];
476	
477	  /**
478	   * Walks the AST (or the subtree under `root`) with semantic context.
479	   * Scope information is replayed from the native scope tree, so
480	   * non-scope nodes pay a single type lookup and nothing else.
481	   */
482	  walk(visitors: Visitors, root?: Node): void;
483	
484	  /**
485	   * The async counterpart of {@link Module.walk}: identical traversal
486	   * order and mutation semantics, with every handler awaited before
487	   * the walk moves on.
488	   */
489	  walkAsync(visitors: AsyncVisitors, root?: Node): Promise<void>;
490	
491	  /** Collects every node of the given type(s), in source order. */
492	  findAll<K extends NodeType>(type: K): NodeOfType<K>[];
493	  findAll<K extends NodeType>(types: Iterable<K>): NodeOfType<K>[];
494	
495	  /** Import records, in source order. */
496	  readonly imports: Import[];
497	  /** Export records, in source order. */
498	  readonly exports: Export[];
499	  /** Modules this module imports from. Links on demand. */
500	  readonly dependencies: Module[];
501	  /** Modules that import from this module. Links on demand. */
502	  readonly dependents: Module[];
503	}
504	
505	/** A symbol's defining site, possibly in another module. */
506	interface Definition {
507	  readonly module: Module;
508	  /**
509	   * The defining symbol, or null when the definition is a whole module
510	   * namespace (`import * as ns`, `export * as ns`).
511	   */
512	  readonly symbol: Symbol | null;
513	}
514	
515	/** A cross-module reference, as reported by {@link Analyzer.referencesOf}. */
516	interface ModuleReference {
517	  readonly module: Module;
518	  readonly reference: Reference;
519	}
520	
521	/** Options for {@link analyze}: {@link AddFileOptions} plus the module path. */
522	interface AnalyzeOptions extends AddFileOptions {
523	  /**
524	   * The path recorded on the module, also the default source of
525	   * `lang` and `sourceType`.
526	   * @default "input.js"
527	   */
528	  path?: string;
529	}
530	
531	/**
532	 * Parses and analyzes a single file, the shorthand for one-file
533	 * semantics: scopes, symbols, resolved references, and a semantic
534	 * walk. Cross-file surfaces stay empty, use {@link Analyzer} and
535	 * {@link Analyzer.addFile} for multi-file projects and linking.
536	 *
537	 * ```ts
538	 * const module = analyze(`const x = 1; x;`, { lang: "ts" });
539	 * module.walk({ Identifier(node, ctx) { ctx.symbol; } });
540	 * ```
541	 */
542	declare function analyze(source: string, options?: AnalyzeOptions): Module;
543	
544	/**
545	 * The project: a set of analyzed modules and the links between them.
546	 *
547	 * ```ts
548	 * const analyzer = new Analyzer();
549	 * analyzer.addFile("src/app.tsx", source);
550	 * const sym = analyzer.module("src/app.tsx")!.symbolOf(node);
551	 * const def = sym?.definition();
552	 * ```
553	 */
554	declare class Analyzer {
555	  constructor(options?: AnalyzerOptions);
556	
557	  /**
558	   * Parses and analyzes one file natively, returning its {@link Module}.
559	   * Adding an existing path replaces it and marks the graph for
560	   * relinking.
561	   */
562	  addFile(path: string, source: string, options?: AddFileOptions): Module;
563	  /** Removes a file. Returns whether it existed. */
564	  removeFile(path: string): boolean;
565	  /** The module added under `path`, if any. */
566	  module(path: string): Module | undefined;
567	  /** All modules, keyed by path. */
568	  readonly modules: ReadonlyMap<string, Module>;
569	  /** Graph-level diagnostics. Links on demand. */
570	  readonly diagnostics: LinkDiagnostic[];
571	
572	  /**
573	   * Joins imports to exports across every added module: resolves
574	   * specifiers through the host resolver, populates
575	   * {@link Import.resolvedModule}, {@link Module.dependencies} /
576	   * {@link Module.dependents}, and reports unresolvable or ambiguous
577	   * names. Resolution follows the spec's ResolveExport semantics: a
578	   * name supplied by multiple `export *` declarations through
579	   * different bindings is an error, and `"default"` is never satisfied
580	   * by `export *`.
581	   *
582	   * Calling this is optional: every cross-file surface links on demand
583	   * after files change. Call it explicitly to control when the work
584	   * (and its diagnostics) happen.
585	   */
586	  link(): void;
587	
588	  /**
589	   * Follows import -> export -> re-export chains to the symbol that
590	   * actually defines `symbol`. A null `symbol` in the result means a
591	   * module namespace. Returns null when the chain leaves the added
592	   * file set (external modules), does not resolve, or is ambiguous.
593	   */
594	  definitionOf(symbol: Symbol): Definition | null;
595	
596	  /**
597	   * Every reference to `symbol` across the whole graph: local uses
598	   * plus uses of every import binding that resolves back to it.
599	   */
600	  referencesOf(symbol: Symbol): ModuleReference[];
601	}
602	
603	/** Resolves a {@link SourceLang} from a file path's extension. */
604	declare function langFromPath(path: string): SourceLang;
605	
606	/** Resolves a {@link SourceType} from a file path's extension. */
607	declare function sourceTypeFromPath(path: string): SourceType;
608	
609	export {
610	  analyze,
611	  Analyzer,
612	  SymbolFlags,
613	  langFromPath,
614	  sourceTypeFromPath,
615	  type AddFileOptions,
616	  type AnalyzeOptions,
617	  type AnalyzerOptions,
618	  type AsyncVisitors,
619	  type AsyncWalkHandler,
620	  type AsyncWalkHooks,
621	  type Capture,
622	  type Definition,
623	  type Export,
624	  type Import,
625	  type LinkDiagnostic,
626	  type Module,
627	  type ModuleReference,
628	  type NodeOfType,
629	  type NodeType,
630	  type Reference,
631	  type Scope,
632	  type ScopeKind,
633	  type Space,
634	  type Symbol,
635	  type Visitors,
636	  type WalkContext,
637	  type WalkHandler,
638	  type WalkHooks,
639	};
