import { render } from 'react-dom';
import App from "./pages/_app.tsx";
import Page, { getStaticProps } from "./pages/index.tsx";

const container = document.getElementById("__next");
if (container === null)
	throw new Error(
		'Next static migration: the entry document has no #__next element to mount into.',
	);

function mount(pageProps) {
	const tree = createElement(App, { Component: Page, pageProps });
	render(tree, container);
}

Promise.resolve(getStaticProps({ params: {} })).then((result) => {
	if (result === null || typeof result !== 'object')
		throw new Error(
			'Next static migration: getStaticProps returned no result object.',
		);
	if ('notFound' in result || 'redirect' in result)
		throw new Error(
			'Next static migration: getStaticProps asked for a routing outcome (notFound or redirect), which a build with no router cannot honour.',
		);
	mount('props' in result ? result.props : {});
});

